-- SmartLearn core curriculum + lessons (D1 / SQLite). IDs are TEXT (ULID/UUID generated by the app).
PRAGMA foreign_keys = ON;

CREATE TABLE curriculum_sources (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  source_url TEXT,
  origin TEXT NOT NULL CHECK (origin IN ('kicd_official','licensed_third_party','smartlearn_original')),
  license TEXT,
  attribution TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE curriculum_versions (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','retired')),
  effective_from TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE education_levels (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  sort_order INTEGER NOT NULL
);

CREATE TABLE grades (
  id TEXT PRIMARY KEY,               -- e.g. 'grade-5'
  level_id TEXT NOT NULL REFERENCES education_levels(id),
  name TEXT NOT NULL,                -- 'Grade 5'
  sort_order INTEGER NOT NULL
);

CREATE TABLE pathways (               -- Senior School only; optional everywhere else
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL
);

CREATE TABLE subjects (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT
);

-- Which subjects exist in which grade under which curriculum version.
-- pathway_id is nullable: not every subject relationship has a pathway.
CREATE TABLE grade_subjects (
  id TEXT PRIMARY KEY,
  curriculum_version_id TEXT NOT NULL REFERENCES curriculum_versions(id),
  grade_id TEXT NOT NULL REFERENCES grades(id),
  subject_id TEXT NOT NULL REFERENCES subjects(id),
  pathway_id TEXT REFERENCES pathways(id),
  source_id TEXT REFERENCES curriculum_sources(id),
  verified INTEGER NOT NULL DEFAULT 0,
  UNIQUE (curriculum_version_id, grade_id, subject_id, pathway_id)
);

CREATE TABLE strands (
  id TEXT PRIMARY KEY,
  grade_subject_id TEXT NOT NULL REFERENCES grade_subjects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  verified INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE sub_strands (
  id TEXT PRIMARY KEY,
  strand_id TEXT NOT NULL REFERENCES strands(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  verified INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE learning_outcomes (
  id TEXT PRIMARY KEY,
  sub_strand_id TEXT NOT NULL REFERENCES sub_strands(id) ON DELETE CASCADE,
  description TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  verified INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE lessons (
  id TEXT PRIMARY KEY,
  sub_strand_id TEXT NOT NULL REFERENCES sub_strands(id),
  title TEXT NOT NULL,
  estimated_minutes INTEGER,
  language TEXT NOT NULL DEFAULT 'en',
  version INTEGER NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','in_review','published','retired')),
  author_id TEXT,
  reviewer_id TEXT,
  published_at TEXT,
  source_id TEXT REFERENCES curriculum_sources(id),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- Section types follow the 10-step lesson structure; content is JSON so formats can vary.
CREATE TABLE lesson_sections (
  id TEXT PRIMARY KEY,
  lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  section_type TEXT NOT NULL,        -- introduction | outcomes | explanation | example | activity | practice | reflection ...
  title TEXT,
  content_json TEXT NOT NULL,        -- {"text": "...", "media": [...]}
  sort_order INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE lesson_outcomes (
  lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  outcome_id TEXT NOT NULL REFERENCES learning_outcomes(id) ON DELETE CASCADE,
  PRIMARY KEY (lesson_id, outcome_id)
);

CREATE INDEX idx_grade_subjects_grade ON grade_subjects(grade_id, curriculum_version_id);
CREATE INDEX idx_strands_gs ON strands(grade_subject_id, sort_order);
CREATE INDEX idx_substrands_strand ON sub_strands(strand_id, sort_order);
CREATE INDEX idx_outcomes_ss ON learning_outcomes(sub_strand_id, sort_order);
CREATE INDEX idx_lessons_ss ON lessons(sub_strand_id, status);
CREATE INDEX idx_sections_lesson ON lesson_sections(lesson_id, sort_order);
